export function selectionBounds(start,end){const x=Math.min(start.x,end.x),y=Math.min(start.y,end.y);return {x,y,width:Math.abs(end.x-start.x),height:Math.abs(end.y-start.y)};}
export function intersectsRect(a,b){return a.x+a.width>=b.x&&a.x<=b.x+b.width&&a.y+a.height>=b.y&&a.y<=b.y+b.height;}
export function collectSelected(rect,items,base=[]){const result=new Set(base);for(const item of items)if(intersectsRect(rect,item))result.add(item.id);return result;}
export function arrangeDesktopIcons(count,width,height){const total=Math.min(32,Math.max(0,Math.floor(Number.isFinite(count)?count:0)));const w=Math.max(88,Number.isFinite(width)?width:390),h=Math.max(96,Number.isFinite(height)?height:600);const mobile=w<700;const columns=Math.max(1,Math.floor(w/96));const rows=Math.max(1,Math.floor((h-16)/100));return Array.from({length:total},(_,i)=>{const col=mobile?i%columns:Math.floor(i/rows),row=mobile?Math.floor(i/columns):i%rows;return {x:Math.min(Math.max(0,w-88),8+col*96),y:Math.min(Math.max(0,h-96),8+row*100)};});}
